arguments.content:
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const htmlPath = path.resolve('/app/poster.html');
  const outPath = path.resolve('/app/output/final_poster.png');

  const browser = await chromium.launch({
    headless: true,
    executablePath: '/root/.cache/ms-playwright/chromium-1148/chrome-linux/chrome',
  });

  const page = await browser.newPage({
    viewport: { width: 1200, height: 1700 },
    deviceScaleFactor: 2,
  });

  const fileUrl = 'file://' + htmlPath;
  await page.goto(fileUrl, { waitUntil: 'networkidle' });

  // Wait for fonts
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(1000);

  // Screenshot the exact poster area
  const poster = await page.$('.poster');
  await poster.screenshot({
    path: outPath,
    type: 'png',
  });

  await browser.close();
  console.log('Saved to', outPath);
})();

